def subdeep(slug):
    x=SUBDEEP.get(slug)
    if not x: return ""
    rows="".join(f"<tr><th>{esc(k)}</th><td>{esc(v)}</td></tr>" for k,v in x["facts"])
    return f'<h2>The quick version</h2><p>{x["intro"]}</p><table>{rows}</table>{x["body"]}{fhtml(x["faq"])}'
def subld(h,slug,ti):
    x=SUBDEEP.get(slug)
    out=[crumbs([("Home",""),(CN[h][0],h+"/"),(ti,f"{h}/{slug}/")])]
    if x: out.append(faqld(x["faq"]))
    return out
ABOUT_HTML=f'''<p><b>Trends Incoming is {TAG.lower()}.</b> The internet throws a thousand things at you every day. We pick the ones that actually matter: the drop, the trailer, the chart-topper, the deadline, the meme your cousin's going to send you tomorrow.</p><p>Every card gets a short take on why it's trending, plus links to the original source and the conversation on TikTok, Instagram, X and more.</p>
<h2 id="editorial-policy">Editorial policy</h2><ul><li><b>Sources first.</b> Dates, prices, figures and quotes come from official sources (agencies, leagues, studios, companies) or established news outlets, and we link them on the page. When something isn't confirmed, we say so.</li><li><b>Official vs projected.</b> Numbers that aren't final, like tax projections, are labeled as projections, with whose estimate it is and how it was made.</li><li><b>Neutral on politics.</b> We cover elections and policy without endorsing candidates or parties, and link sources from across the spectrum.</li><li><b>No advice.</b> Money, health and legal pages are general information, not personal advice. Stock pages carry a full disclaimer.</li><li><b>Independent.</b> We're not affiliated with the brands, platforms or leagues we cover. We may show Google ads and may use affiliate or sponsored links, which are disclosed (see our <a href="../advertising-disclosure/">advertising and affiliate disclosure</a>) and never influence our reporting.</li><li><b>Dates you can trust.</b> Each page shows when it was last updated, and its first-published date when that's different.</li></ul>
<h2 id="corrections">Corrections policy</h2><p>If we get something wrong, we fix it fast. Factual errors are corrected on the page as soon as we confirm them, and the page's updated date changes. Significant corrections (a wrong date, number or name that changes the meaning) get a short note on the page saying what changed. We don't quietly rewrite history.</p><p>Full details are on our <a href="../corrections/">Corrections Policy page</a>. Spotted an error? Email <a href="mailto:{EMAIL}">{EMAIL}</a> with the page link and what needs fixing, or use the <a href="../contact/">contact form</a>.</p>
<h2 id="contact">Contact</h2><p><b>{LLC}</b><br>5640 W Maple Rd, Ste 101<br>West Bloomfield, MI 48322<br>United States</p><p>Email: <a href="mailto:{EMAIL}">{EMAIL}</a></p><p>Trends Incoming is written by The Trends Incoming team and owned and operated by {LLC}, a Florida limited liability company.</p>'''
